int expon; frexpf((float)inputSample, &expon); fpd ^= fpd > 17; fpd ^= fpd << 5; inputSample +=(((double(fpd)-uint32 t(0x7fffffffffffffffffffffffffffffffffffffffffffffffff)) * 5.5e-36l * pow(2,expon+62));

